static bool IsEnvVarSet(string name)
{
    // .NET 9 breaking change: empty env vars on Linux now return null
    // instead of "". Check /proc/self/environ to distinguish
    // "not set" from "explicitly empty".
    try
    {
        var environ = System.IO.File.ReadAllText("/proc/self/environ");
        return environ.Split('\0').Any(e =>
            e == name + "=" || e.StartsWith(name + "=", StringComparison.Ordinal));
    }
    catch
    {
        return false;
    }

